function interact(){if(player.inCar){player.inCar=false;player.x=player.car.x+Math.cos(player.car.a+Math.PI/2)*34;player.y=player.car.y+Math.sin(player.car.a+Math.PI/2)*34;player.car.speed=0;notify('You stepped out. Take in the city.');return;}let near=null,dist=72;for(const c of cars){let d=Math.hypot(player.x-c.x,player.y-c.y);if(d<dist){near=c;dist=d;}}if(near){player.inCar=true;player.car=near;notify('You hopped into an old Ambassador.');return;}let m=missions[missionIndex];if(m&&Math.hypot(player.x-marker.x,player.y-marker.y)<90){if(missionStep===0){missionStep=1;marker.x=m.target.x;marker.y=m.target.y;notify(missionIndex===0?'Parcel collected. Bring it to the tea stall!':'Picked up. Now deliver it to the next stop.');}else{cash+=m.reward;missionIndex++;missionStep=0;if(missionIndex<missions.length){marker.x=missions[missionIndex].start.x;marker.y=missions[missionIndex].start.y;}else{marker.x=-9999;notify('All stories complete. '+`₹${m.reward.toLocaleString('en-IN')} earned — enjoy free roam!`);}updateHUD();return;}updateHUD();}else notify('Nothing to do here — explore the neighborhood.');}
function clamp(v){return Math.max(12,Math.min(WORLD-12,v));}
function blocked(x,y){let lx=(x%TILE),ly=(y%TILE);return lx>ROAD+3&&ly>ROAD+3;}
function move(dt){if(!started)return;let p=player;let up=keys.w||keys.arrowup,down=keys.s||keys.arrowdown,left=keys.a||keys.arrowleft,right=keys.d||keys.arrowright;
 if(p.inCar){let c=p.car,acc=(up?1:0)-(down?1:0);c.speed+=acc*310*dt;c.speed*=Math.pow(keys[' ']?.88:.985,dt*60);c.speed=Math.max(-120,Math.min(260,c.speed));if(left)c.a-=dt*(1.8+Math.abs(c.speed)*.006)*Math.sign(c.speed||1);if(right)c.a+=dt*(1.8+Math.abs(c.speed)*.006)*Math.sign(c.speed||1);let nx=clamp(c.x+Math.cos(c.a)*c.speed*dt),ny=clamp(c.y+Math.sin(c.a)*c.speed*dt);if(!blocked(nx,ny)){c.x=nx;c.y=ny;}else c.speed*=-.2;p.x=c.x;p.y=c.y;p.a=c.a;$('#speed').textContent=Math.round(Math.abs(c.speed)*.36);}else{let dx=(right?1:0)-(left?1:0),dy=(down?1:0)-(up?1:0),len=Math.hypot(dx,dy)||1,speed=keys.shift?190:125;dx=dx/len*speed*dt;dy=dy/len*speed*dt;let nx=clamp(p.x+dx),ny=clamp(p.y+dy);if(!blocked(nx,p.y))p.x=nx;if(!blocked(p.x,ny))p.y=ny;if(dx||dy){p.a=Math.atan2(dy,dx);p.walk+=dt*10;}$('#speed').textContent=keys.shift?'12':'0';}
 camera.x+=(p.x-W/2-camera.x)*Math.min(1,dt*5);camera.y+=(p.y-H/2-camera.y)*Math.min(1,dt*5);if(missionIndex<3){let m=missions[missionIndex];if(!missionStep){marker.x=m.start.x;marker.y=m.start.y;}let distance=Math.hypot(p.x-marker.x,p.y-marker.y);if(distance<100&&Math.hypot(p.x-m.start.x,p.y-m.start.y)>220&&missionStep===0){marker.x=m.start.x;marker.y=m.start.y;}}if(toastTimer>0){toastTimer-=dt;if(toastTimer<=0)$('#toast').classList.remove('show');}updateHUD();}
function drawRoads(){ctx.fillStyle='#ab9a79';ctx.fillRect(0,0,WORLD,WORLD);for(let y=0;y<WORLD;y+=TILE){for(let x=0;x<WORLD;x+=TILE){ctx.fillStyle='#b9aa89';ctx.fillRect(x+ROAD,y+ROAD,TILE-ROAD,TILE-ROAD);ctx.fillStyle='#d5c9aa';ctx.fillRect(x+ROAD+4,y+ROAD+4,TILE-ROAD-8,TILE-ROAD-8);}}ctx.fillStyle='#485455';for(let x=0;x<WORLD;x+=TILE)ctx.fillRect(x,0,ROAD,WORLD);for(let y=0;y<WORLD;y+=TILE)ctx.fillRect(0,y,WORLD,ROAD);
 // asphalt edge, lanes, and faded yellow center lines
 ctx.strokeStyle='#e3c765';ctx.lineWidth=2;ctx.setLineDash([14,18]);for(let x=ROAD/2;x<WORLD;x+=TILE){ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,WORLD);ctx.stroke();}for(let y=ROAD/2;y<WORLD;y+=TILE){ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(WORLD,y);ctx.stroke();}ctx.setLineDash([]);
 // tram rails through the central city
 ctx.strokeStyle='#8c9390';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(TILE*4+10,TILE);ctx.lineTo(TILE*4+10,WORLD);ctx.moveTo(TILE*4+25,TILE);ctx.lineTo(TILE*4+25,WORLD);ctx.stroke();for(let y=140;y<WORLD;y+=34){ctx.strokeStyle='#9da19a';ctx.beginPath();ctx.moveTo(TILE*4+7,y);ctx.lineTo(TILE*4+28,y);ctx.stroke();}}
function drawBuildings(){for(const b of buildings){let x=b.x,y=b.y,w=b.w,h=b.h;if(x+w<camera.x-60||x>camera.x+W+60||y+h<camera.y-60||y>camera.y+H+60)continue;ctx.fillStyle='#7a6550';ctx.fillRect(x+6,y+9,w,h);ctx.fillStyle=b.c;ctx.fillRect(x,y,w,h);ctx.fillStyle='rgba(255,244,208,.42)';ctx.fillRect(x+5,y+5,w-10,6);ctx.fillStyle='#5b5347';for(let xx=x+13;xx<x+w-9;xx+=27)for(let yy=y+20;yy<y+h-10;yy+=27){ctx.fillStyle='#514c42';ctx.fillRect(xx,yy,10,12);ctx.fillStyle='#dac59d';ctx.fillRect(xx+2,yy+2,6,8);}ctx.fillStyle='#9d4f3d';ctx.fillRect(x+w*.15,y+h*.13,w*.7,15);ctx.fillStyle='#f0d7a4';ctx.font='bold 8px monospace';ctx.fillText(['MISTI','TEA HOUSE','BOOKS','PHARMACY','HOTEL'][Math.floor(rand(b.seed+2)*5)],x+w*.15+3,y+h*.13+10);}}
function drawTrees(){for(const t of trees){if(t.x<camera.x-25||t.x>camera.x+W+25||t.y<camera.y-25||t.y>camera.y+H+25)continue;if((t.x%TILE)<ROAD+8||(t.y%TILE)<ROAD+8)continue;ctx.fillStyle='#294c3c';ctx.beginPath();ctx.ellipse(t.x+3,t.y+5,t.r,t.r*.72,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#568259';ctx.beginPath();ctx.arc(t.x,t.y,t.r*.8,0,Math.PI*2);ctx.fill();}}
function drawCar(c){ctx.save();ctx.translate(c.x,c.y);ctx.rotate(c.a);ctx.fillStyle='#202928';ctx.fillRect(-21,-13,43,27);ctx.fillStyle=c.color;ctx.fillRect(-23,-11,44,22);ctx.fillStyle='#adc1bc';ctx.fillRect(-8,-9,15,18);ctx.fillStyle='#273434';ctx.fillRect(-6,-8,11,16);ctx.fillStyle='#f6d697';ctx.fillRect(18,-8,3,5);ctx.fillRect(18,3,3,5);ctx.fillStyle='#252a29';ctx.fillRect(-14,-14,9,3);ctx.fillRect(9,-14,9,3);ctx.fillRect(-14,11,9,3);ctx.fillRect(9,11,9,3);if(c.kind==='taxi'){ctx.fillStyle='#e2c34c';ctx.fillRect(-4,-12,9,4);}ctx.restore();}
function drawPerson(p){ctx.save();ctx.translate(p.x,p.y);ctx.rotate(p.a);ctx.fillStyle='#252c29';ctx.beginPath();ctx.ellipse(2,3,5,8,0,0,Math.PI*2);ctx.fill();ctx.fillStyle=p.shirt;ctx.fillRect(-4,-5,9,10);ctx.fillStyle='#d7aa83';ctx.beginPath();ctx.arc(0,-8,4,0,Math.PI*2);ctx.fill();ctx.restore();}
function drawPlayer(){ctx.save();ctx.translate(player.x,player.y);ctx.rotate(player.a);ctx.fillStyle='#26312f';ctx.beginPath();ctx.ellipse(1,4,7,10,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#d9f36a';ctx.fillRect(-5,-6,11,13);ctx.fillStyle='#d8a57e';ctx.beginPath();ctx.arc(0,-9,4,0,Math.PI*2);ctx.fill();ctx.restore();}
function drawMarker(time){if(marker.x<0)return;let pulse=1+Math.sin(time*4)*.12;ctx.save();ctx.translate(marker.x,marker.y);ctx.strokeStyle='#eafa76';ctx.lineWidth=3;ctx.globalAlpha=.7;ctx.beginPath();ctx.ellipse(0,0,25*pulse,13*pulse,0,0,Math.PI*2);ctx.stroke();ctx.globalAlpha=.28;ctx.fillStyle='#d9f36a';ctx.beginPath();ctx.ellipse(0,0,21*pulse,10*pulse,0,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1;ctx.fillStyle='#eafa76';ctx.font='bold 13px monospace';ctx.textAlign='center';ctx.fillText('✦',0,-20-Math.sin(time*4)*4);ctx.restore();}
function drawWorld(time){ctx.clearRect(0,0,W,H);ctx.save();ctx.translate(-camera.x,-camera.y);ctx.fillStyle='#ab9a79';ctx.fillRect(0,0,WORLD,WORLD);drawRoads();drawBuildings();drawTrees();for(const p of people)if(p.x>camera.x-30&&p.x<camera.x+W+30&&p.y>camera.y-30&&p.y<camera.y+H+30)drawPerson(p);for(const c of cars)if(c.x>camera.x-40&&c.x<camera.x+W+40&&c.y>camera.y-40&&c.y<camera.y+H+40)drawCar(c);drawMarker(time);if(!player.inCar)drawPlayer();ctx.restore();}
function drawMap(){let w=mapCanvas.width,h=mapCanvas.height,s=0.07;mctx.fillStyle='#9c9070';mctx.fillRect(0,0,w,h);mctx.fillStyle='#465354';for(let x=0;x<WORLD;x+=TILE){let px=x/WORLD*w;mctx.fillRect(px,0,ROAD/TILE*w,w);}for(let y=0;y<WORLD;y+=TILE){let py=y/WORLD*h;mctx.fillRect(0,py,w,ROAD/TILE*h);}mctx.fillStyle='#d7c7a6';for(const b of buildings)mctx.fillRect(b.x/WORLD*w,b.y/WORLD*h,b.w/WORLD*w,b.h/WORLD*h);if(marker.x>=0){mctx.fillStyle='#e8f678';mctx.beginPath();mctx.arc(marker.x/WORLD*w,marker.y/WORLD*h,4,0,Math.PI*2);mctx.fill();}mctx.fillStyle='#fff';mctx.beginPath();mctx.arc(player.x/WORLD*w,player.y/WORLD*h,4,0,Math.PI*2);mctx.fill();mctx.strokeStyle='#ffffff77';mctx.lineWidth=1;mctx.strokeRect(player.x/WORLD*w-11,player.y/WORLD*h-11,22,22);}
let last=performance.now(),elapsed=0;function frame(now){let dt=Math.min(.04,(now-last)/1000);last=now;elapsed+=dt;move(dt);drawWorld(elapsed);if(started)drawMap();requestAnimationFrame(frame);}requestAnimationFrame(frame);
})();
