const canvas=document.querySelector('#game'),ctx=canvas.getContext('2d'),mapCanvas=document.querySelector('#map'),mctx=mapCanvas.getContext('2d');let W=0,H=0,dpr=1;
function resize(){dpr=Math.min(devicePixelRatio||1,2);W=innerWidth;H=innerHeight;canvas.width=W*dpr;canvas.height=H*dpr;ctx.setTransform(dpr,0,0,dpr,0,0);mapCanvas.width=296;mapCanvas.height=296;}addEventListener('resize',resize);resize();
const TILE=360,ROAD=100,WORLD=3600,keys={},rand=n=>{let x=Math.sin(n*127.1+311.7)*43758.5453;return x-Math.floor(x)};
const zones=['NORTH KOLKATA','COLLEGE STREET','BOWBAZAR','ESPLANADE','PARK STREET','PRINSEP GHAT','HOWRAH BRIDGE','BURRABAZAR','SOUTH KOLKATA'];
let player={x:1640,y:1680,a:-Math.PI/2,walk:0,inCar:false,car:null},camera={x:0,y:0},cash=1250,started=false,toastTimer=0,missionIndex=0,missionStep=0;
let cars=[],people=[],buildings=[],trees=[];const carColors=['#cf4e3b','#e6b94e','#6d9a89','#d7d0bc','#7c8ec0','#e18a4d'];
for(let row=0;row<10;row++)for(let col=0;col<10;col++){let bx=col*TILE,by=row*TILE,seed=row*19+col*13;buildings.push({x:bx+ROAD+10,y:by+ROAD+10,w:TILE-ROAD-24,h:TILE-ROAD-24,c:['#c98259','#d6bd8b','#9eab8b','#b86e52','#d4c7a6','#a8a987'][Math.floor(rand(seed)*6)],seed});if(rand(seed+4)>.42)buildings.push({x:bx+ROAD+17,y:by+ROAD+TILE*.55,w:TILE*.27,h:TILE*.26,c:'#d7c6a2',seed:seed+9});}
function addCar(x,y,a,color,kind='ambassador'){cars.push({x,y,a,color,kind,speed:0});}addCar(1650,1710,-Math.PI/2,'#d7c6a2');
for(let i=0;i<42;i++){let x=160+rand(i+30)*WORLD,y=160+rand(i+90)*WORLD,roadX=Math.round(x/TILE)*TILE+ROAD/2,roadY=Math.round(y/TILE)*TILE+ROAD/2;if(rand(i+3)>.5){x=roadX;y=Math.round(y/70)*70+25;}else{x=Math.round(x/70)*70+25;y=roadY;}addCar(x,y,rand(i+120)>.5?0:Math.PI/2,carColors[Math.floor(rand(i+70)*carColors.length)],rand(i+10)>.75?'taxi':'ambassador');}
for(let i=0;i<100;i++)people.push({x:rand(i+210)*WORLD,y:rand(i+310)*WORLD,a:rand(i+410)*6.28,phase:rand(i+500)*10,shirt:['#c75d47','#d6b84e','#628d7b','#747fa5','#dbd0b4'][i%5]});for(let i=0;i<140;i++){let x=rand(i+600)*WORLD,y=rand(i+700)*WORLD;trees.push({x,y,r:8+rand(i+800)*8});}
const missions=[{title:'Morning adda',text:'Find the parcel near College Street.',start:{x:1650,y:1600},target:{x:1290,y:1290},hint:'PARCEL PICKUP · COLLEGE STREET',reward:500},{title:'Tram-time delivery',text:'Take the hot rolls to the tram stop.',start:{x:1290,y:1290},target:{x:2350,y:2010},hint:'ROLLS DELIVERY · ESPLANADE',reward:800},{title:'Across the river',text:'Meet your friend at Prinsep Ghat.',start:{x:2350,y:2010},target:{x:2620,y:2450},hint:'EVENING MEETUP · PRINSEP GHAT',reward:1200}];
const marker={x:missions[0].start.x,y:missions[0].start.y},$=s=>document.querySelector(s);
function notify(text){const t=$('#toast');t.textContent=text;t.classList.add('show');toastTimer=2.5;}
function updateHUD(){let m=missions[missionIndex];$('#cash').textContent='₹ '+cash.toLocaleString('en-IN');$('#missionType').textContent=missionIndex===3?'Free roam · Kolkata':'Story · 0'+(missionIndex+1);$('#missionTitle').textContent=missionIndex===3?'The city is yours':m.title;$('#missionText').textContent=missionIndex===3?'Take the long way home. More stories are always around the corner.':(missionStep===0?m.text:'Bring it to '+m.hint.split(' · ')[0].toLowerCase()+'.');$('#progress').style.width=missionStep?'55%':'0%';let zone=zones[Math.min(8,Math.floor(player.x/400)+Math.floor(player.y/400))];$('#location').textContent=zone+' · KOLKATA';$('#vehicleLabel').textContent=player.inCar?'AMBASSADOR · '+zone:'ON FOOT · '+zone;}
